{
  "interpretation": {
    "name": "Line1NutrunnerTighteningAndReturn",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Reserve the shared nutrunner NR7, bring it to station st1, tighten the F25 fasteners per the MES program, evaluate and record the result, then return the tool to the crib and release it.",
    "constraints": [
      "The tool is reserved exclusively for line 1 and released only after it is back in the crib",
      "The tool must be at the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program; no numeric process values in the Recipe",
      "Every tightening is evaluated and recorded for traceability",
      "transport-tool is delegated to the Executor agvexecutor",
      "Every tool-using Step renews the lease and depends on reserve-tool; each Step is shorter than the 120 s lease"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "This request only, executed once now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tightening-with-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {"name": "reserve-nr7", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "fetch-program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {"name": "configure-nr7", "service": "configure-tool", "next": ["tighten-nr7"], "dep": ["fetch-program", "reserve-nr7", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten-nr7", "service": "tighten-fasteners", "next": [], "dep": ["configure-nr7", "reserve-nr7", "transport-to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {"name": "evaluate-result", "service": "evaluate-tightening", "next": [], "dep": ["tighten-nr7", "fetch-program"], "executor": null, "params": {}},
          {"name": "record-result", "service": "record-tightening", "next": [], "dep": ["tighten-nr7"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release-nr7"], "dep": ["reserve-nr7"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve-nr7"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
